function adicionarUsuario(e,t){let a=document.getElementById("listaUsuarios"),i=document.createElement("li");i.className="list-group-item",i.textContent=`${e} - ${t}`,a.appendChild(i)}function carregarUsuarios(){fetch("data/fake-api.json").then(e=>e.json()).then(e=>{e.forEach(e=>{adicionarUsuario(e.nome,e.email)})}).catch(e=>console.error("Erro AJAX:",e))}document.addEventListener("DOMContentLoaded",()=>{let e=document.getElementById("cadastroForm");document.getElementById("listaUsuarios");let t=document.getElementById("toggleTheme");e.addEventListener("submit",t=>{t.preventDefault();let a=document.getElementById("nome").value,i=document.getElementById("email").value;adicionarUsuario(a,i),e.reset()}),t.addEventListener("click",()=>{document.body.classList.toggle("dark-theme"),document.body.classList.toggle("light-theme")}),carregarUsuarios()});